    if (index >= 0 && typeof result.success === 'boolean') {
        queue.splice(index, 1);
        acceptedResults.push(id);
        global.set('lastCommandResult', { id, success: result.success, error: result.error || null, timestamp: new Date().toISOString() });
    }
