} else {
    const age = Date.now() - Date.parse(state.receivedAt || state.timestamp || 0);
    msg.payload = { ...state, connected: state.connected === true && age < 6000, message: age >= 6000 ? 'Sin comunicación reciente con el puente' : state.message };
}
msg.payload.lastCommand = global.get('lastCommandResult') || null;
