const validValues = command && Array.isArray(command.values) && command.values.length > 0;
const validData = validType && validAddress && validValues && (command.type !== 'coils' || command.values.every(value => typeof value === 'boolean')) && (command.type !== 'holding_registers' || command.values.every(value => Number.isInteger(value) && value >= 0 && value <= 65535));
